css:
.ml-root {
  color-scheme: light;
  --paper: #f4ede0;
  --ink: #1f1d1a;
  --muted: #666055;
  --line: #d9d1c3;
  --soft: #eae2d4;
  font-family: 'Roboto', 'Noto Naskh Arabic', sans-serif;
  color: var(--ink);
  background: var(--paper);
  font-synthesis: none;
  -webkit-font-smoothing: antialiased;

  scroll-padding-top: 36px;
}
* { box-sizing: border-box; }
.ml-body { margin: 0; font-size: 16px; line-height: 1.6; }
a { color: inherit; text-underline-offset: 4px; }
a:hover { text-decoration-thickness: 2px; }
button, a { -webkit-tap-highlight-color: transparent; }
button { font: inherit; }
a, button, summary { touch-action: manipulation; }
a:focus-visible, button:focus-visible, summary:focus-visible, iframe:focus-visible { outline: 2px solid var(--ink); outline-offset: 6px; }
[hidden] { display: none !important; }
h1, h2, h3, p { margin: 0; }
h2 { font-size: 23px; line-height: 1.35; font-weight: 600; letter-spacing: -.55px; }
svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; flex: none; }
.shell { max-width: 1104px; margin-inline: auto; padding-inline: 32px; }
.header { display: flex; align-items: center; justify-content: space-between; min-height: 112px; gap: 28px; }
.logo { display: inline-flex; padding-block: 8px; flex: none; }
.logo img { display: block; width: 157px; height: auto; }
nav { display: flex; align-items: center; gap: 28px; font-size: 14px; }
nav a { text-decoration: none; }
nav a:hover { text-decoration: underline; }
.language { position: relative; }
.language summary { display: grid; place-items: center; width: 44px; height: 44px; border-radius: 50%; list-style: none; cursor: pointer; }
summary::-webkit-details-marker { display: none; }
.language summary:hover, .language[open] summary { background: var(--soft); }
.language-options { position: absolute; inset-inline-end: 0; z-index: 2; min-width: 140px; padding: 5px; border: 1px solid var(--line); border-radius: 12px; background: var(--paper); box-shadow: 0 5px 18px #1f1d1a12; }
.language-options a { display: flex; align-items: center; justify-content: space-between; padding: 7px 12px; border-radius: 8px; }
.language-options a:hover, .language-options a:focus-visible { background: var(--soft); text-decoration: none; }
.language-options a[aria-current]::after { content: '✓' / ''; }
.main { max-width: 792px; padding: 0 28px; margin-inline: auto; outline: none; }
.hero { padding: 70px 0 40px; }
.eyebrow { display: inline-flex; align-items: center; gap: 9px; color: var(--muted); text-decoration: none; font-size: 13px; margin-bottom: 23px; }
.eyebrow:hover { color: var(--ink); text-decoration: underline; }
h1 { font-size: clamp(42px, 21.011999999999997px, 62px); line-height: 1.08; font-weight: 600; letter-spacing: -2.5px; }
h1 span { color: #777065; }
.intro { margin-top: 25px; max-width: 590px; font-size: 19px; line-height: 1.65; color: #514c44; text-wrap: pretty; }
.actions, .stores { display: flex; align-items: center; flex-wrap: wrap; }
.actions { margin-top: 26px; gap: 8px 22px; }
.stores { gap: 8px; }
.button { display: inline-flex; gap: 9px; align-items: center; justify-content: center; padding: 10px 17px; min-height: 44px; border: 1px solid var(--line); border-radius: 28px; text-decoration: none; font-size: 15px; font-weight: 500; }
.button:hover { background: var(--soft); }
.button.preferred { background: var(--ink); border-color: var(--ink); color: var(--paper); }
.button.preferred:hover { background: #38342d; }
.arrow { display: none; width: 16px; height: 16px; }
.button.preferred .arrow { display: inline; }
.watch-link { display: inline-flex; align-items: center; gap: 7px; font-size: 15px; text-decoration: none; min-height: 44px; }
.watch-link:hover { text-decoration: underline; }
.play-icon { width: 16px; height: 16px; fill: currentColor; stroke: none; }
[dir=rtl] :is(.play-icon, .arrow) { transform: scaleX(-1); }
.free { margin-top: 10px; font-size: 14px; color: var(--muted); }
.film-section h2 { margin-bottom: 12px; font-size: 17px; letter-spacing: -.25px; }
.film { position: relative; aspect-ratio: 16/9; background: var(--ink); border-radius: 12px; overflow: hidden; isolation: isolate; }
.film iframe, .film-play img { display: block; width: 100%; height: 100%; border: 0; }
.film-play img { position: absolute; inset: 0; z-index: -1; }
.film-play { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: flex-end; gap: 10px; padding: 0 16px 34px; color: var(--paper); text-decoration: none; font-size: 13px; }
.film-play:focus-visible { outline-color: var(--paper); outline-offset: -8px; border-radius: 12px; }
.play-circle { display: grid; place-items: center; width: 48px; height: 48px; border-radius: 50%; border: 1px solid #746e64; background: #39352d; }
.play-circle .play-icon { width: 20px; height: 20px; }
.film-play:hover .play-circle { background: var(--paper); color: var(--ink); }
.youtube-link { display: inline-block; margin-top: 12px; color: var(--muted); font-size: 13px; }
.how { padding-top: 72px; }
.steps { padding: 0; margin: 30px 0 0; list-style: none; display: grid; gap: 25px; }
.steps li { display: flex; gap: 19px; align-items: flex-start; }
.step-number { margin-top: 1px; display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; flex: none; font-size: 13px; border: 1px solid var(--line); border-radius: 50%; color: var(--muted); }
.steps h3 { font-size: 16px; font-weight: 600; line-height: 1.65; }
.steps p { font-size: 15px; max-width: 590px; color: var(--muted); margin-top: 4px; }
.control-note { display: flex; align-items: flex-start; gap: 16px; padding: 22px 0; margin: 30px 0 0 47px; border-block: 1px solid var(--line); }
.player-glyph { width: 33px; height: 33px; display: flex; align-items: center; justify-content: center; flex: none; margin-top: 3px; border-radius: 50%; background: var(--ink); }
.control-note p { color: var(--muted); font-size: 14px; }
.control-note strong { color: var(--ink); font-weight: 500; }
.questions { margin-top: 70px; }
.faq-list { margin-top: 24px; }
.faq-list details { border-bottom: 1px solid var(--line); }
.faq-list summary { list-style: none; cursor: pointer; display: flex; justify-content: space-between; align-items: center; gap: 20px; padding-block: 19px; font-size: 15px; font-weight: 500; }
.plus { width: 12px; height: 12px; position: relative; flex: none; color: var(--muted); }
.plus::before, .plus::after { content: ''; position: absolute; }
.plus::before { width: 12px; border-top: 1px solid; top: 5.5px; }
.plus::after { height: 12px; border-left: 1px solid; left: 5.5px; }
.faq-list details[open] .plus::after { display: none; }
details p { max-width: 650px; font-size: 15px; line-height: 1.75; color: var(--muted); padding: 0 26px 21px 0; }
.footer { margin-top: 90px; padding-block: 28px 36px; display: flex; justify-content: space-between; gap: 18px; align-items: baseline; border-top: 1px solid var(--line); color: var(--muted); font-size: 13px; }
.footer nav { flex-wrap: wrap; gap: 6px 22px; font-size: 13px; }
.footer nav a[aria-current] { color: var(--ink); }
.footer p a { color: var(--ink); }
.skip { position: fixed; z-index: 10; top: 12px; inset-inline-start: 12px; padding: 10px 20px; background: var(--ink); color: var(--paper); transform: translateY(-200%); }
.skip:focus { transform: none; }
[lang=ar] .ml-body { font-family: 'Roboto', 'Noto Naskh Arabic', sans-serif; line-height: 1.9; }
[lang=ar] h1, [lang=ar] h2, [lang=ar] h3 { font-family: 'Alexandria Site', 'Roboto', 'Noto Naskh Arabic', sans-serif; letter-spacing: 0; }
[lang=ar] h1 { font-size: clamp(36px, 18.54px, 52px); line-height: 1.55; font-weight: 500; }
[lang=ar] h2 { font-size: 20px; line-height: 1.7; }
[lang=ar] .film-section h2 { font-size: 16px; }
[lang=ar] h3 { font-size: 15px; font-weight: 500; }
[lang=ar] .intro { font-size: 19px; line-height: 1.95; }
[lang=ar] .button { font-size: 16px; }
[lang=ar] .control-note { margin: 30px 47px 0 0; }
[lang=ar] details p { padding: 0 0 21px 26px; }
/* About, Privacy policy, Terms of use and Contact & support */
.page { padding-block: 64px 8px; }
.page > * { max-width: 660px; }
.page h1 { font-size: clamp(36px, 18.128px, 46px); line-height: 1.15; letter-spacing: -1.4px; text-wrap: balance; }
.page p { margin-top: 14px; font-size: 17px; line-height: 1.75; text-wrap: pretty; overflow-wrap: break-word; }
.page .lead { margin-top: 22px; font-size: 19px; line-height: 1.65; color: #514c44; }
.page .updated { margin-top: 14px; font-size: 14px; color: var(--muted); }
.page h2 { margin-top: 46px; }
.page h2 + p { margin-top: 10px; }
[lang=ar] .page h1 { font-size: clamp(32px, 16.067999999999998px, 40px); line-height: 1.55; letter-spacing: 0; }
[lang=ar] .page p { line-height: 1.95; }
  .shell { padding-inline: 24px; }
  .header { min-height: 90px; }
  .logo img { width: 140px; }
  .section-link { display: none; }
  .main { padding-inline: 24px; }
  .hero { padding-top: 42px; padding-bottom: 32px; }
  h1 { letter-spacing: -1.6px; }
  .intro { font-size: 17px; margin-top: 23px; }
  .actions { gap: 2px 14px; }
  .button { padding-inline: 14px; }
  .film-play { padding-bottom: 18px; gap: 7px; }
  .play-circle { width: 38px; height: 38px; }
  .how { padding-top: 48px; }
  .control-note { margin-inline: 0; }
  [lang=ar] .control-note { margin-inline: 0; }
  .questions { margin-top: 48px; }
  .footer { margin-top: 64px; flex-direction: column; gap: 16px; }
  [lang=ar] .intro { font-size: 17px; }
  .page { padding-top: 40px; }
  .page h1 { letter-spacing: -1px; }
  .page .lead { font-size: 17px; }
  .page p { font-size: 16px; }
  .page h2 { margin-top: 38px; }
.visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
.audio-modes { display: flex; gap: 28px; border-bottom: 1px solid var(--line); margin-top: 30px; }
.audio-modes button { position: relative; background: none; border: 0; color: var(--muted); padding: 4px 0 14px; min-height: 44px; font-size: 15px; font-weight: 500; cursor: pointer; }
.audio-modes button[aria-selected=true] { color: var(--ink); }
.audio-modes button[aria-selected=true]::after { content: ''; position: absolute; inset-inline: 0; bottom: -1px; height: 2px; background: var(--ink); }
.audio-modes button:hover { color: var(--ink); }
.audio-intro { max-width: 600px; margin-block: 22px 20px; font-size: 17px; }
.audio-workspace { display: flex; flex-direction: column; min-height: 286px; padding: 20px; border: 1px solid var(--line); border-radius: 14px; background: #faf6ee; }
.audio-workspace[data-state=empty] { border-style: dashed; }
.audio-workspace.dragging { outline: 2px solid var(--ink); outline-offset: 4px; background: var(--soft); }
.audio-workspace h2 { font-size: 20px; letter-spacing: -.4px; line-height: 1.4; }
.audio-workspace hr { width: 100%; border: 0; border-top: 1px solid var(--line); margin-block: 16px 22px; }
.audio-empty { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 20px; text-align: center; padding-block: 16px; }
.audio-empty h2 + p { margin-top: 8px; }
.audio-small, .audio-meta { color: var(--muted); font-size: 14px; line-height: 1.65; }
.audio-hint { color: var(--muted); font-size: 13px; line-height: 1.6; text-align: center; text-wrap: pretty; }
.audio-primary { min-height: 48px; padding: 11px 20px; background: var(--ink); color: var(--paper); border-color: var(--ink); cursor: pointer; }
.audio-primary:hover { background: #38342d; }
.audio-primary:disabled { background: var(--soft); border-color: var(--line); color: var(--muted); cursor: not-allowed; }
.audio-text { background: none; border: 0; padding: 8px 0; min-height: 44px; color: var(--muted); text-decoration: underline; text-underline-offset: 4px; font-size: 14px; cursor: pointer; flex: none; }
.audio-text:hover { color: var(--ink); }
.audio-file-row { display: flex; align-items: center; gap: 16px; min-height: 58px; }
.audio-file-type { font-family: 'Noto Sans Mono', monospace; font-size: 12px; letter-spacing: .06em; color: var(--muted); flex: none; min-width: 32px; }
.audio-file-info { flex: 1; min-width: 0; }
.audio-file-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 16px; font-weight: 500; }
.audio-meta { margin-top: 4px; font-variant-numeric: tabular-nums; }
.audio-ready { display: grid; gap: 17px; flex: 1; align-content: end; }
.audio-progress-content { display: grid; gap: 15px; }
#audio-remaining { margin-top: -10px; font-variant-numeric: tabular-nums; }
#audio-remaining:empty { display: none; }
.audio-status-heading { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.audio-percent { color: var(--muted); font-variant-numeric: tabular-nums; flex: none; }
.audio-workspace progress { width: 100%; height: 6px; border: 0; border-radius: 999px; overflow: hidden; appearance: none; background: var(--soft); accent-color: var(--ink); }
.audio-workspace progress::-webkit-progress-bar { background: var(--soft); border-radius: 999px; }
.audio-workspace progress::-webkit-progress-value { background: var(--ink); border-radius: 999px; }
.audio-workspace progress::-moz-progress-bar { background: var(--ink); border-radius: 999px; }
.audio-workspace progress:not([value]) { opacity: .55; }
.audio-cancel { margin-top: auto; display: flex; justify-content: flex-end; padding-top: 10px; }
.audio-listen { display: flex; align-items: center; gap: 20px; margin-top: 14px; }
.audio-listen button { background: none; border: 0; border-bottom: 1px solid transparent; padding: 6px 0; min-height: 44px; font-size: 14px; color: var(--muted); cursor: pointer; }
.audio-listen button[aria-pressed=true] { border-color: var(--ink); color: var(--ink); }
.audio-player { display: flex; align-items: center; gap: 14px; margin-block: 14px 22px; }
.audio-play { display: grid; place-items: center; width: 44px; height: 44px; flex: none; border: 1px solid var(--line); border-radius: 50%; background: none; color: var(--ink); cursor: pointer; }
.audio-play:hover { background: var(--soft); }
.audio-player input { flex: 1; min-width: 0; width: 100%; height: 28px; accent-color: var(--ink); cursor: pointer; }
.audio-player input:focus-visible { outline: 2px solid var(--ink); outline-offset: 3px; }
.audio-time { white-space: nowrap; color: var(--muted); font-size: 13px; font-variant-numeric: tabular-nums; }
.audio-done-actions { display: grid; gap: 6px; margin-top: auto; padding-top: 16px; }
.audio-error { display: grid; gap: 10px; }
.audio-privacy { display: flex; gap: 7px; align-items: center; justify-content: center; margin-top: 17px; font-size: 14px; color: var(--muted); }
.audio-privacy svg { width: 16px; height: 16px; }
[lang=ar] .audio-workspace h2 { font-size: 18px; line-height: 1.7; }
[lang=ar] .audio-intro { font-size: 17px; }
  .audio-workspace { padding: 16px; min-height: 300px; }
  .audio-file-row { gap: 10px; }
  .audio-workspace h2 { font-size: 18px; }
  .audio-intro { font-size: 16px; }
  .audio-player { gap: 8px; }
  .audio-privacy { font-size: 13px; }
  .audio-time { font-size: 12px; }
.mode-files #youtube-panel, .mode-files [data-youtube-section], .mode-files [data-youtube-questions] { display: none !important; }
.mode-youtube #files-panel, .mode-youtube [data-files-questions] { display: none !important; }
